{
  "title": "CSCI-344: Programming Language Concepts - Foundations",
  "learningObjectives": [
    "Identify the core syntactic and semantic components of high-level programming languages as defined in the course catalog.",
    "Explain how problem-solving methods like decomposition, abstraction, and correctness arguments apply across diverse language implementations.",
    "Differentiate between language-specific details and general principles of programming language design using comparative analysis."
  ],
  "beats": [
    {
      "title": "Course Scope and Prerequisites",
      "claim": "CSCI-344 studies the syntax and semantics of diverse high-level languages to demonstrate general principles of design and implementation, emphasizing concepts over specific details",
      "example": "The course requires prior completion of CSCI-243 or equivalent, ensuring students have foundational programming knowledge before tackling language theory",
      "visualDirection": "Display the official RIT catalog description text with highlighted keywords: 'syntax', 'semantics', 'general principles', 'concepts underpinning modern languages'",
      "sourceIds": ["rit-csci-344"]
    },
    {
      "title": "Problem-Solving Foundations",
      "claim": "Programming begins with precise problem statements, input/output examples, and algorithms written independently of any specific syntax",
      "example": "A student defines a sorting algorithm using pseudocode before choosing Python or Java to implement it, ensuring the logic remains language-agnostic",
      "visualDirection": "Show a split-screen: left side displays a generic problem statement with inputs/outputs; right side shows the same logic in abstract pseudocode",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Core Language Constructs",
      "claim": "Variables represent values and state, expressions compute values, and control structures select or repeat operations within any high-level language",
      "example": "In both Python and C++, a variable holds a state (e.g., a counter), an expression calculates a new value (e.g., counter + 1), and a loop repeats until a condition fails",
      "visualDirection": "Animate a simple counter incrementing via an expression, with a loop control structure governing the repetition, labeled generically without syntax",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Functions and Decomposition",
      "claim": "Functions decompose a solution into named operations with parameters and results, reducing the number of interacting concerns",
      "example": "A student breaks a complex data-processing task into separate functions for reading input, transforming data, and writing output, each with clear parameters",
      "visualDirection": "Illustrate a flowchart where a large problem box splits into three smaller labeled boxes (Read, Transform, Write) connected by arrows",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case to terminate the process",
      "example": "Calculating factorial(n) recursively calls factorial(n-1) until reaching the base case factorial(0) = 1",
      "visualDirection": "Draw a tree diagram showing factorial(5) branching into factorial(4), factorial(3), etc., with a highlighted leaf node labeled 'Base Case'",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Structures and Representations",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access, trees represent hierarchy, and graphs represent connected entities",
      "example": "A queue processes job requests in arrival order (FIFO), while a stack manages undo operations in reverse order (LIFO)",
      "visualDirection": "Display four distinct icons: a linear list, a stack with arrows pointing down, a queue with arrows pointing right, and a tree/graph structure",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Python-Specific Language Mechanics",
      "claim": "Python objects have identity, a type, and a value; names are bound to objects within namespaces and scopes, and exceptions interrupt normal control flow",
      "example": "Two variables referencing the same list object share identity, while a raised exception halts execution until caught by a handler",
      "visualDirection": "Show a Python REPL snippet with `id()` output for two variables pointing to the same list, followed by a simple `try/except` block catching an error",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Correctness and Testing",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases",
      "example": "A student writes unit tests for a sorting function that include edge cases like empty lists and already-sorted inputs to verify correctness",
      "visualDirection": "Present a table with columns: 'Test Case', 'Input', 'Expected Output', 'Actual Output', highlighting a failing row that gets traced",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Abstraction and Contracts",
      "claim": "Programs should be reasoned about through explicit state, control flow, data representation, contracts, and observable behavior",
      "example": "Defining a contract for a `max()` function that guarantees it returns the largest element without modifying the input list",
      "visualDirection": "Display a pseudo-code block with a precondition (input is non-empty) and postcondition (output equals the maximum element)",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "To analyze any programming language concept, verify: (1) problem statement clarity, (2) decomposition into functions, (3) data structure choice, (4) recursion base case, (5) test/b",
      "example": "When evaluating a new language feature, a student checks if it adheres to these five criteria before implementing it in a project",
      "visualDirection": "Render a checklist graphic with five numbered items, each accompanied by a small icon (e.g., magnifying glass for problem statement, gears for decomposition)",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-344"]
    }
  ]
}
